func CreateClientFactory(config FactoryConfig) (ClientFactory, error) {
	switch config.Type {
	case TYPE_SQLITE, TYPE_DEFAULT:
		return NewSQLiteClientFactory(config.Database), nil
	case TYPE_POSTGRES:
		return NewPostgreSQLClientFactory(config), nil
	default:
		return NewSQLiteClientFactory(config.Database), nil
	}
}

pkg.adapters.database.clients.postgres.P.source_code:
func (f *PostgreSQLClientFactory) CreateClient() (*gorm.DB, error) {
	// Set defaults
	config := f.config
	if config.Host == "" {
		config.Host = "localhost"
	}
	if config.Port == 0 {
		config.Port = 5432
	}
	if config.SSLMode == "" {
		config.SSLMode = "disable"
	}

	// Build PostgreSQL DSN
	dsn := fmt.Sprintf("host=%s user=%s password=%s dbname=%s port=%d sslmode=%s",
		config.Host, config.Username, config.Password, config.Database, config.Port, config.SSLMode)

	db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		return nil, fmt.Errorf("failed to open PostgreSQL database: %w", err)
	}

	// Configure connection pool for PostgreSQL
	sqlDB, err := db.DB()
	if err != nil {
		return nil, fmt.Errorf("failed to get underlying sql.DB: %w", err)
	}
	sqlDB.SetMaxOpenConns(25)
	sqlDB.SetMaxIdleConns(5)

	return db, nil
}

pkg.adapters.database.clients.sqlite.SQL.source_code:
func (f *SQLiteClientFactory) CreateClient() (*gorm.DB, error) {
	if err := os.MkdirAll(filepath.Dir(f.dbPath), 0750); err != nil {
		return nil, fmt.Errorf("failed to create database directory: %w", err)
	}

	db, err := gorm.Open(sqlite.Open(f.dbPath), &gorm.Config{
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		return nil, fmt.Errorf("failed to open SQLite database: %w", err)
	}

	// Configure connection pool for SQLite
	sqlDB, err := db.DB()
	if err != nil {
		return nil, fmt.Errorf("failed to get underlying sql.DB: %w", err)
	}
	sqlDB.SetMaxOpenConns(1) // SQLite works best with single connection

	return db, nil
}

pkg.adapters.database.database.NewDataba.source_code:
func NewDatabase(config DatabaseConfig) (ports.Database, error) {
	// Create the appropriate client factory
	clientFactory, err := clients.CreateClientFactory(clients.FactoryConfig{
		Type:     config.Type,
		Host:     config.Host,
		Port:     config.Port,
		Database: config.Database,
		Username: config.Username,
		Password: config.Password,
		SSLMode:  config.SSLMode,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to create client factory: %w", err)
	}

	// Create the database client
	db, err := clientFactory.CreateClient()
	if err != nil {
		return nil, fmt.Errorf("failed to create database client: %w", err)
	}

	// Create the shared storage implementation
	return NewGormDB(db)
}

pkg.adapters.database.database.NewGormDB.source_code:
func NewGormDB(db *gorm.DB) (*GormDB, error) {
	gormDB := &GormDB{db: db}

	// Auto-migrate the RowStats model
	if err := gormDB.createTables(); err != nil {
		return nil, fmt.Errorf("failed to create tables: %w", err)
	}

	return gormDB, nil
}

pkg.adapters.database.database.GormDB.cr.source_code:
func (s *GormDB) createTables() error {
	// Use GORM's AutoMigrate for both new and existing tables
	if err := s.db.AutoMigrate(&Stats{}); err != nil {
		return fmt.Errorf("failed to auto-migrate RowStats: %w", err)
	}
	if err := s.db.AutoMigrate(&OOMEvent{}); err != nil {
		return fmt.Errorf("failed to auto-migrate OOMEvent: %w", err)
	}
	return nil
}

