	m.mu.RLock()
	defer m.mu.RUnlock()

	result := make(map[string]*ClusterClients)
	for id, clients := range m.clusterClients {
		result[id] = clients
	}

	return result
}

func (m *SingleClusterManager) GetClusterIDs() []string {
	m.mu.RLock()
	defer m.mu.RUnlock()

	ids := make([]string, 0, len(m.clusterClients))
	for id := range m.clusterClients {
		ids = append(ids, id)
	}

	return ids
}

